// FEATURES.md, generated by verify's manifest step. Session 3 extends it with each feature's
// slots, routes and content; until then it lists feature folders only.

export function featuresMd(features: string[]): string {
  const head = '# Features\n\nGenerated by `pnpm verify` (step 2). Do not edit by hand.\n\n';
  if (!features.length) return `${head}No features yet. Woodcutting arrives in session 6.\n`;
  return `${head}| Feature |\n| --- |\n${features.map((f) => `| ${f} |`).join('\n')}\n`;
}
